#!/usr/bin/env node

/**
 * Sync skills from the Agent Skills ecosystem.
 * Fetches reference skills from github.com/anthropics/skills
 * (the official example skills for the agentskills.io open standard).
 */

const https = require('https');
const fs = require('fs');
const path = require('path');

const DATA_DIR = path.join(__dirname, '..', 'data');

// Platforms that support the Agent Skills (SKILL.md) open standard
// Source: https://agentskills.io logo carousel
const AGENT_SKILL_PLATFORMS = [
  'claude-code',
  'codex-cli',
  'gemini-cli',
  'cursor',
  'copilot',
];

function fetch(url) {
  return new Promise((resolve, reject) => {
    const parsedUrl = new URL(url);
    const options = {
      hostname: parsedUrl.hostname,
      path: parsedUrl.pathname + parsedUrl.search,
      headers: {
        'User-Agent': 'awesome-agent-skills-sync/1.0',
        Accept: 'application/vnd.github+json',
      },
    };

    // Use GITHUB_TOKEN if available for rate limiting
    if (process.env.GITHUB_TOKEN) {
      options.headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
    }

    const req = https.get(options, (res) => {
      if (res.statusCode === 301 || res.statusCode === 302) {
        return fetch(res.headers.location).then(resolve, reject);
      }
      if (res.statusCode !== 200) {
        return reject(new Error(`HTTP ${res.statusCode} for ${url}`));
      }
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => resolve(data));
    });
    req.on('error', reject);
    req.setTimeout(30000, () => {
      req.destroy();
      reject(new Error('timeout'));
    });
  });
}

/**
 * Parse YAML frontmatter from SKILL.md content.
 */
function parseFrontmatter(content) {
  const match = content.match(/^---\s*\n([\s\S]*?)\n---/);
  if (!match) return {};

  const yaml = match[1];
  const result = {};
  for (const line of yaml.split('\n')) {
    const kv = line.match(/^(\w[\w-]*):\s*"?(.*?)"?\s*$/);
    if (kv) {
      result[kv[1]] = kv[2];
    }
  }
  return result;
}

async function fetchSkillsFromRepo(owner, repo) {
  console.log(`  Fetching skills from ${owner}/${repo}...`);
  const entries = [];

  // List directories in the skills/ folder
  let skillDirs;
  try {
    const raw = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/contents/skills`
    );
    skillDirs = JSON.parse(raw).filter((item) => item.type === 'dir');
  } catch (err) {
    console.error(`  Failed to list skills in ${owner}/${repo}: ${err.message}`);
    return [];
  }

  console.log(`  Found ${skillDirs.length} skill directories`);

  // Fetch SKILL.md for each
  for (const dir of skillDirs) {
    try {
      const raw = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/contents/skills/${dir.name}/SKILL.md`
      );
      const file = JSON.parse(raw);
      const content = Buffer.from(file.content, 'base64').toString('utf-8');
      const frontmatter = parseFrontmatter(content);

      const name = frontmatter.name || dir.name;
      const description = frontmatter.description || '';

      entries.push({
        id: `${owner}/${repo}/${dir.name}`,
        name,
        description: description.replace(/^["']|["']$/g, ''),
        url: `https://github.com/${owner}/${repo}/tree/main/skills/${dir.name}`,
        category: 'agent-skill',
        platforms: AGENT_SKILL_PLATFORMS,
        source: 'agentskills-io',
        section: 'Official Example Skills',
        githubOwner: owner,
        githubRepo: repo,
        stars: null, // filled in by sync-github-stars.js
        lastUpdated: new Date().toISOString(),
      });
    } catch (err) {
      console.error(`  Failed to fetch SKILL.md for ${dir.name}: ${err.message}`);
    }
  }

  return entries;
}

async function main() {
  console.log('Syncing Agent Skills (agentskills.io standard)...\n');

  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

  // Fetch from the official Anthropic skills repo
  const entries = await fetchSkillsFromRepo('anthropics', 'skills');

  console.log(`\n  ${entries.length} skills synced`);

  const outputPath = path.join(DATA_DIR, 'agentskills-io.json');
  fs.writeFileSync(outputPath, JSON.stringify(entries, null, 2));
  console.log(`  Written to ${outputPath}`);

  // Summary
  const summary = {
    lastSync: new Date().toISOString(),
    source: 'agentskills-io',
    totalEntries: entries.length,
    repos: ['anthropics/skills'],
  };
  fs.writeFileSync(
    path.join(DATA_DIR, 'agentskills-io-summary.json'),
    JSON.stringify(summary, null, 2)
  );
}

main().catch((err) => {
  console.error('Agent Skills sync failed:', err);
  process.exit(1);
});

"use client";

import { useState, useMemo } from "react";
import SkillCard from "./SkillCard";
import { Skill, CATEGORY_META, PLATFORM_META } from "@/lib/types";

const PAGE_SIZE = 48;

export default function SkillBrowser({
  skills,
  initialCategory,
}: {
  skills: Skill[];
  initialCategory?: string;
}) {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState(initialCategory || "");
  const [platform, setPlatform] = useState("");
  const [sort, setSort] = useState<"stars" | "name">("stars");
  const [page, setPage] = useState(0);

  const filtered = useMemo(() => {
    let result = skills;
    if (category) result = result.filter((s) => s.category === category);
    if (platform) result = result.filter((s) => s.platforms.includes(platform));
    if (query) {
      const q = query.toLowerCase();
      result = result.filter(
        (s) =>
          s.name.toLowerCase().includes(q) ||
          s.description.toLowerCase().includes(q) ||
          s.id.toLowerCase().includes(q) ||
          (s.section && s.section.toLowerCase().includes(q))
      );
    }
    if (sort === "stars") {
      result = [...result].sort((a, b) => (b.stars || 0) - (a.stars || 0));
    } else {
      result = [...result].sort((a, b) => a.name.localeCompare(b.name));
    }
    return result;
  }, [skills, query, category, platform, sort]);

  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  const availableCategories = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const s of skills) {
      counts[s.category] = (counts[s.category] || 0) + 1;
    }
    return Object.entries(CATEGORY_META)
      .filter(([slug]) => (counts[slug] || 0) > 0)
      .map(([slug, meta]) => ({ slug, label: meta.label, count: counts[slug] || 0 }));
  }, [skills]);

  const availablePlatforms = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const s of skills) {
      for (const p of s.platforms) {
        counts[p] = (counts[p] || 0) + 1;
      }
    }
    return Object.entries(PLATFORM_META)
      .filter(([key]) => (counts[key] || 0) > 0)
      .map(([key, meta]) => ({ key, label: meta.label, count: counts[key] || 0 }));
  }, [skills]);

  return (
    <div>
      {/* Search + Filters */}
      <div className="mb-6 space-y-3">
        <input
          type="text"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setPage(0);
          }}
          placeholder="Search skills, MCP servers, tools..."
          className="w-full rounded-lg border border-zinc-300 bg-white px-4 py-2.5 text-sm text-zinc-900 placeholder-zinc-400 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-100 dark:placeholder-zinc-500"
        />
        <div className="flex flex-wrap gap-2">
          {!initialCategory && (
            <select
              value={category}
              onChange={(e) => {
                setCategory(e.target.value);
                setPage(0);
              }}
              className="rounded-md border border-zinc-300 bg-white px-3 py-1.5 text-sm dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-100"
            >
              <option value="">All categories</option>
              {availableCategories.map((c) => (
                <option key={c.slug} value={c.slug}>
                  {c.label} ({c.count})
                </option>
              ))}
            </select>
          )}
          <select
            value={platform}
            onChange={(e) => {
              setPlatform(e.target.value);
              setPage(0);
            }}
            className="rounded-md border border-zinc-300 bg-white px-3 py-1.5 text-sm dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-100"
          >
            <option value="">All platforms</option>
            {availablePlatforms.map((p) => (
              <option key={p.key} value={p.key}>
                {p.label} ({p.count})
              </option>
            ))}
          </select>
          <select
            value={sort}
            onChange={(e) => setSort(e.target.value as "stars" | "name")}
            className="rounded-md border border-zinc-300 bg-white px-3 py-1.5 text-sm dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-100"
          >
            <option value="stars">Most stars</option>
            <option value="name">Name A-Z</option>
          </select>
        </div>
      </div>

      {/* Results count */}
      <div className="mb-4 text-sm text-zinc-500 dark:text-zinc-400">
        {filtered.length.toLocaleString()} results
        {query && ` for "${query}"`}
      </div>

      {/* Grid */}
      {paged.length > 0 ? (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {paged.map((skill) => (
            <SkillCard key={skill.id} skill={skill} />
          ))}
        </div>
      ) : (
        <div className="py-12 text-center text-zinc-500">
          No skills found. Try a different search or filter.
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="mt-8 flex items-center justify-center gap-2">
          <button
            onClick={() => setPage(Math.max(0, page - 1))}
            disabled={page === 0}
            className="rounded-md border border-zinc-300 px-3 py-1.5 text-sm disabled:opacity-40 dark:border-zinc-700"
          >
            Previous
          </button>
          <span className="text-sm text-zinc-500">
            Page {page + 1} of {totalPages}
          </span>
          <button
            onClick={() => setPage(Math.min(totalPages - 1, page + 1))}
            disabled={page >= totalPages - 1}
            className="rounded-md border border-zinc-300 px-3 py-1.5 text-sm disabled:opacity-40 dark:border-zinc-700"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

